record.field:
for task in records:
    if not task.du_an_id:
        continue
    if task.trang_thai == 'moi':
        continue
    project = task.du_an_id
    tasks = env['cong_viec'].search([('du_an_id', '=', project.id)])
    total = len(tasks)
    completed = len(tasks.filtered(lambda t: t.trang_thai == 'hoan_thanh'))
    progress = (completed / total * 100) if total > 0 else 0.0

    nguoi_bao_cao = project.phu_trach_id
    if not nguoi_bao_cao:
        # Tìm bất kỳ nhân viên nào (fallback)
        nguoi_bao_cao = env['hr.employee'].search([], limit=1)
    if not nguoi_bao_cao:
        continue

    env['bao_cao_tien_do_du_an'].create({
        'du_an_id': project.id,
        'ngay_bao_cao': datetime.date.today(),
        'tien_do': progress,
        'noi_dung': f'Tự động tạo khi công việc {task.ma_cv} thay đổi trạng thái thành {task.trang_thai}',
        'nguoi_bao_cao_id': nguoi_bao_cao.id,
    })
